import { serve } from "inngest/next";
import { inngest } from "@/lib/inngest/client";
import { sendUserReminder } from "@/lib/inngest/functions";

// Registers Notely's background jobs with Inngest. In dev, point the
// Inngest Dev Server at this route (see README) and it will discover
// `sendUserReminder` automatically; in production Inngest Cloud calls back
// into this route to invoke each step.
export const { GET, POST, PUT } = serve({
  client: inngest,
  functions: [sendUserReminder],
});

