import { inngest } from "@/lib/inngest/client";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function createUser(input: {
  email: string;
  name: string;
}): Promise<User> {
  const user: User = {
    id: String(nextId++),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedule the 10-minute welcome reminder as a background job (see
  // src/lib/inngest/functions.ts). Sending the event just enqueues it —
  // Inngest owns the delay and retries from here, so this doesn't block
  // or fail user creation if the job itself has trouble later.
  await inngest.send({
    name: "user/created",
    data: { userId: user.id, email: user.email, name: user.name },
  });

  return user;
}

